  function profileRank(tierValue,rankValue) {
    let tier=num(tierValue),rank=num(rankValue);
    if(tier==null||tier<0||tier>27)return {name:'—',icon:null};
    if(tier===26&&rank>0&&rank<=100)tier=27;
    const groups=['Bronze','Silver','Gold','Platinum','Diamond'],romans=['V','IV','III','II','I'];
    const base=tier===0?'Qualifying':tier===26?'Master':tier===27?'Grandmaster':groups[Math.floor((tier-1)/5)];
    const name=tier===0?tr('generated.players.unranked','Unranked'):tier>=26?base:base+' '+romans[(tier-1)%5];
    const suffix=tier>0&&tier<26?'_'+(5-(tier-1)%5):'';
    return {name,icon:'/images/rank-tiers/'+base.toLowerCase()+'/RankIcon_'+base+suffix+'.avif'};
  }
